#include <cassert>
#include <iostream>
#include <cmath>
#include <functional>
#include <vector>

using namespace std;

long long int max_diff_in_array(vector<long long int> &a, int exception);

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int tc;
    cin >> tc;

    while (tc--) {
        int n;
        cin >> n;

        vector<long long int> a(n);

        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }

        if (n == 1) {
            cout << 1 << endl;
            continue;
        }

        assert(n >= 2);

        // a <- (0, 10^18)

        // Odd number of elements
        if (n % 2 == 1) {
            // Case: Needle is placed at the start, it couples with 1st element - say
            // a b c
            // -> <? a> <b c>
            // -> 1 <b c>

            long long int s_diff = 1; // (clubs with element at idx 0)
            for (int i = 1; i < n; i += 2) {
                s_diff = max(s_diff, a[i + 1] - a[i]);
            }

            // Case: Needle is placed at the end, it couples with last element - say
            // a b c
            // -> <a b> <c ?>
            // -> <a b> 1

            long long int e_diff = 1;
            for (int i = 0; i < n - 1; i += 2) {
                e_diff = max(e_diff, a[i + 1] - a[i]);
            }

            long long int min_diff = min(s_diff, e_diff);

            // Case: Needle is placed just before the element at idx `i`
            //
            // Sub Case: Even `i`
            // a b ? c d e
            //     |--> Case i = 2
            // ? is coupled with c, element to the right which is element at idx i
            //
            // Sub Case: Odd `i`
            // a b c ? d e
            //       |--> Case i = 3
            // ? is coupled with c, element to the left which is element at idx i - 1
            //
            // More examples:
            // a ? b c
            //   |--> Case i = 1
            //
            for (int i = 1; i < n; ++i) {
                long long int m_diff = -1;

                if (a[i] == a[i - 1] + 1) {
                    continue;
                }
                const int coupled_with = (i % 2 == 1) ? i - 1 : i;
                for (int j = 0; j < n;) {
                    if (j == coupled_with) {
                        m_diff = max(m_diff, 1ll);
                        ++j;
                    } else {
                        m_diff = max(m_diff, a[j + 1] - a[j]);
                        j += 2;
                    }
                }
                if (m_diff != -1) {
                    min_diff = min(min_diff, m_diff);
                }
            }

            cout << min_diff << endl;
        }
        // Even number of elements
        else {
            long long int diff = -1;
            for (int i = 0; i < n; i += 2) {
                diff = max(diff, a[i + 1] - a[i]);
            }
            cout << diff << endl;
        }
    }
}
